// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface ICrowdfunding {
    function isContributor(uint _id, address _user) external view returns (bool);
}

contract Governance {
    ICrowdfunding public crowdfunding;

    // Optimized struct: packed for gas efficiency
    struct Request {
        uint amount;              // 256-bit (1 slot)
        address payable recipient;// 160-bit (shares with finalized in 1 slot)
        bool finalized;           // 8-bit (shares slot with recipient)
        uint voteCount;           // 256-bit (1 slot)
        string description;       // Dynamic (separate storage)
    }

    // Events for gas-efficient indexing
    event RequestCreated(uint indexed campaignId, uint indexed requestId, string description, uint amount, address indexed recipient);
    event Voted(uint indexed campaignId, uint indexed requestId, address indexed voter);
    event RequestFinalized(uint indexed campaignId, uint indexed requestId, uint voteCount);

    mapping(uint => mapping(uint => Request)) public requests;
    mapping(uint => uint) public requestCountByCampaign;
    mapping(uint => mapping(uint => mapping(address => bool))) public hasVoted;

    constructor(address _crowdfundingAddress) {
        require(_crowdfundingAddress != address(0), "Invalid crowdfunding address");
        crowdfunding = ICrowdfunding(_crowdfundingAddress);
    }

    function createRequest(uint _campaignId, string memory _desc, uint _amount, address payable _recipient) public {
        require(_amount > 0, "Amount must be > 0");
        require(_recipient != address(0), "Invalid recipient");

        requestCountByCampaign[_campaignId]++;
        uint requestId = requestCountByCampaign[_campaignId];

        // Packed struct initialization
        requests[_campaignId][requestId] = Request(_amount, _recipient, false, 0, _desc);
        
        emit RequestCreated(_campaignId, requestId, _desc, _amount, _recipient);
    }

    function voteRequest(uint _campaignId, uint _requestId) public {
        require(crowdfunding.isContributor(_campaignId, msg.sender), "Only contributors can vote");
        require(!hasVoted[_campaignId][_requestId][msg.sender], "Already voted");
        require(!requests[_campaignId][_requestId].finalized, "Request finalized");

        hasVoted[_campaignId][_requestId][msg.sender] = true;
        requests[_campaignId][_requestId].voteCount++;
        
        emit Voted(_campaignId, _requestId, msg.sender);
    }
}
